const Database = require('better-sqlite3');
const { v4: uuidv4 } = require('uuid');
const db = new Database('/workspace/world.db');

// Get self contact (Emily Carter)
const self = db.prepare(\"SELECT * FROM ts_contacts WHERE is_self = 1\").get();
if (!self) throw new Error('No self contact found');

// Recipient is also Emily Carter (same phone number)
const recipient = db.prepare(\"SELECT * FROM ts_contacts WHERE phone_number = '+1-312-555-0172'\").get();

const messageId = uuidv4();
db.prepare(\`INSERT INTO ts_messages (message_id, sender_person_id, sender_phone_number, recipient_person_id, recipient_phone_number, content, creation_timestamp) VALUES (?, ?, ?, ?, ?, ?, ?)\`).run(
  messageId,
  self.person_id,
  self.phone_number,
  recipient ? recipient.person_id : null,
  '+1-312-555-0172',
  'This is a test message from Emily Carter.',
  Date.now() / 1000
);

console.log('Message sent! ID:', messageId);

// Verify
const msg = db.prepare('SELECT * FROM ts_messages WHERE message_id = ?').get(messageId);
console.log(JSON.stringify(msg, null, 2));
